using PaperPixelGames.Framework.States.MainMenu;using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using Cysharp.Threading.Tasks;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using UnityEditor;using UnityEditor.SceneManagement;using PaperPixelGames.Core.SaveSystem;using PaperPixelGames.Core.Managers;using PaperPixelGames.Framework.Patterns;using PaperPixelGames.Framework.Input;using SushiAndFish.Casino;using SushiAndFish.Casino.Original;using SushiAndFish.Casino.Original.Extensions;using SushiAndFish.FrontEnd;
[InitializeOnLoad]public static class CasinoUrgentPlayAudit{
 const string K="CasinoUrgent.";static string R=>IslandRevision20261018.Reports;static Report r;static bool ended;static double end;
 [Serializable]public class Report{public string utc,error,stage;public bool ready,tabletOpened,tabletCursor,tabletMapClick,betValid,walletLinked,shoreFalls;public long coins,bet;public float beforeY,afterY;public List<string> colliders=new List<string>();public List<string> meshes=new List<string>();}
 static CasinoUrgentPlayAudit(){if(SessionState.GetBool(K+"active",false))EditorApplication.update+=Tick;}
 public static void Start(){UnityEditor.PlayerSettings.productName="SushiAndFish WorldRepair QA 20261016";SessionState.SetBool(K+"active",true);SessionState.SetBool(K+"started",false);EditorSceneManager.OpenScene("Assets/Scenes/Main.unity");EditorApplication.update+=Tick;EditorApplication.EnterPlaymode();}
 static void Tick(){if(EditorApplication.isPaused)EditorApplication.isPaused=false;if(Application.isPlaying&&!SessionState.GetBool(K+"started",false)){SessionState.SetBool(K+"started",true);Run().Forget();}if(ended&&!EditorApplication.isPlayingOrWillChangePlaymode){UnityEditor.PlayerSettings.productName="Deep Blue Sushi";AssetDatabase.SaveAssets();SessionState.SetBool(K+"active",false);if(EditorApplication.timeSinceStartup-end>2)EditorApplication.Exit(string.IsNullOrEmpty(r.error)?0:1);}}
 static void Stage(string s){r.stage=s;File.WriteAllText(Path.Combine(R,"casino-urgent-play-audit.json"),JsonUtility.ToJson(r,true));}
 static object Prior(string s)=>typeof(WorldIssuePlayAudit).GetMethod(s,BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,null);
 static async UniTask Pause(float s)=>await UniTask.Delay(TimeSpan.FromSeconds(s),ignoreTimeScale:true);
 static async UniTask Wait(Func<bool> f,int seconds=100){var d=DateTime.UtcNow.AddSeconds(seconds);while(!f()){if(DateTime.UtcNow>d)throw new Exception("Timeout "+r.stage);await UniTask.Yield();}}
 static async UniTask Run(){r=new Report{utc=DateTime.UtcNow.ToString("o")};try{
 Stage("MENU");await Wait(()=>{Prior("Dismiss");return IslandFrontEndFlow.Active&&IslandFrontEndFlow.Active.BackdropLoaded;});await Pause(1);Prior("Dismiss");await Singleton<MainMenuManager>.Instance.CustomizationSceneHost.PreloadAsync();IslandFrontEndFlow.Active.ShowLoadGames();await Pause(.5f);Resources.FindObjectsOfTypeAll<SaveSlot>().Where(s=>s&&s.gameObject.scene.name=="MainMenuState"&&s.ContainsSave).OrderBy(s=>s.SlotIndex).First().LaunchOriginalSlot();
 Stage("HOST");await Wait(()=>(bool)Prior("Ready"),160);await Wait(()=>ParkCasinoIntegration.Instance&&ParkCasinoIntegration.Instance.Ready);var c=ParkCasinoIntegration.Instance;r.ready=true;
 foreach(var co in c.ModuleRoot.GetComponentsInChildren<Collider>(true)){var b=co.bounds;if(b.size.x>40&&b.size.z>40)r.colliders.Add(co.name+" enabled="+co.enabled+" "+b);}
 foreach(var m in c.ModuleRoot.GetComponentsInChildren<MeshRenderer>(true)){var b=m.bounds;if(b.size.y<5&&b.size.x>5&&b.size.z>5)r.meshes.Add(m.name+" "+b+" materials="+string.Join(",",m.sharedMaterials.Select(x=>x?x.name:"null")));}
 c.HostEconomy.SetSavedGoldBalance(9000,"9000",c.HostEconomy.ScrapBalance.Value);await Pause(.3f);r.coins=c.WholeCoins;r.walletLinked=NetworkSingleton<MoneyManager>.Instance.balance==90;
 var k=c.ModuleRoot.GetComponentsInChildren<Keypad>(false).FirstOrDefault(x=>x.NetworkcasinoGame);if(k){k.SetBetMinimum();await Pause(.2f);r.bet=k.GetCurrentInput();r.betValid=r.bet>=k.NetworkcasinoGame.MinBet&&r.bet<=90&&string.IsNullOrEmpty(k.Network_errorMessage);}
 var kb=InputSystem.AddDevice<Keyboard>("Urgent QA keyboard");var mouse=InputSystem.AddDevice<Mouse>("Urgent QA mouse");var h=Singleton<InputManager>.Instance.InputHandler;h.InputMap.asset.devices=new InputDevice[]{kb,mouse};
 Stage("TABLET");InputSystem.QueueStateEvent(kb,new KeyboardState(UnityEngine.InputSystem.Key.Tab));await Pause(.15f);InputSystem.QueueStateEvent(kb,new KeyboardState());await Pause(1);r.tabletOpened=c.HostPlayer.IsTabletActive;r.tabletCursor=Cursor.visible&&Cursor.lockState==CursorLockMode.None;
 if(r.tabletOpened){var tab=UnityEngine.Object.FindFirstObjectByType<PaperPixelGames.Core.Tablet.TabletController>();var field=tab.GetType().GetField("_mapAppButton",BindingFlags.Instance|BindingFlags.NonPublic);var mb=(Component)field.GetValue(tab);var rt=mb.GetComponent<RectTransform>();var ca=rt.GetComponentInParent<Canvas>();var screen=RectTransformUtility.WorldToScreenPoint(ca.worldCamera,rt.TransformPoint(rt.rect.center));InputSystem.QueueStateEvent(mouse,new MouseState{position=screen});await Pause(.15f);InputSystem.QueueStateEvent(mouse,new MouseState{position=screen,buttons=1});await Pause(.1f);InputSystem.QueueStateEvent(mouse,new MouseState{position=screen});await Pause(.4f);r.tabletMapClick=tab.GetType().GetField("_currentActiveApp",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(tab) is PaperPixelGames.Core.Tablet.MapApp;InputSystem.QueueStateEvent(kb,new KeyboardState(UnityEngine.InputSystem.Key.Escape));await Pause(.1f);InputSystem.QueueStateEvent(kb,new KeyboardState());await Pause(.6f);}
 Stage("SHORE");var player=c.HostPlayer;player.TeleportPlayer(new Vector3(-157,5,-30),true);player.FirstPersonCharacter.SetVelocity(Vector3.zero);await Pause(.2f);r.beforeY=player.transform.position.y;await Pause(1.7f);r.afterY=player.transform.position.y;r.shoreFalls=r.afterY<r.beforeY-.5f;
 Stage("DONE");}catch(Exception ex){r.error=ex.ToString();Stage("FAILED");Debug.LogException(ex);}finally{ended=true;end=EditorApplication.timeSinceStartup;EditorApplication.ExitPlaymode();}}
}
